schema:
{
  "description": "Scontrini per note spese",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "Data": {
        "type": "date",
        "method": "extract",
        "description": "Data dello scontrino."
      },
      "Totale": {
        "type": "number",
        "method": "extract",
        "description": "Importo dopo \"TOTALE COMPLESSIVO\"."
      },
      "Categoria": {
        "type": "string",
        "method": "classify",
        "enum": [
          "pasti",
          "trasporti",
          "alloggio",
          "altro"
        ],
        "description": "Tipo di spesa in base all'esercente."
      }
    }
  }
}
